// ── Meta-Harness v2: TextGrad-style Dimension Gradients ────────────────────
// Natural-language critiques of individual harness dimensions, generated by
// a cheap LLM call (Haiku-tier). Written to gradient-hints.md in each
// candidate's .metaharness/ directory as advisory hints for the proposer.
//
// Only generated when composite deficit >= GRADIENT_THRESHOLD — no LLM cost
// for well-performing candidates.

import type { LLMClient, ChatCompletionMessageParam } from "../llm.js";
import type { CandidateManifest, DimensionGradient, TraceRecord } from "./types.js";
import { getRegistry } from "./registry.js";
import { extractJSON } from "../utils/json-extract.js";

/** Minimum composite deficit before gradients are generated. */
export const GRADIENT_THRESHOLD = 2;

const MAX_GRADIENTS = 5;

// ── Main entry ─────────────────────────────────────────────────────────────

/**
 * Generate 3-5 dimension gradient critiques for a failing candidate.
 * Returns [] when: no scores, deficit < GRADIENT_THRESHOLD, or LLM fails.
 */
export async function generateDimensionGradients(
    llm: LLMClient,
    candidate: CandidateManifest,
    traces: TraceRecord[],
    benchmarkDetails: Record<string, unknown>,
): Promise<DimensionGradient[]> {
    if (!candidate.scores) return [];

    const bestScore = extractBestScore(benchmarkDetails, candidate.scores.composite);
    const deficit = bestScore - candidate.scores.composite;
    if (deficit < GRADIENT_THRESHOLD) return [];

    const prompt = buildPrompt(candidate, traces, bestScore);

    try {
        const messages: ChatCompletionMessageParam[] = [
            { role: "user", content: prompt },
        ];
        const response = await llm.chat({
            messages,
            systemPrompt: "You are a precise system-optimization critic. Respond with a single JSON array only. No prose, no markdown fences.",
            responseFormat: "json_object",
        });

        const raw = response.choices?.[0]?.message?.content ?? "";
        return parseGradients(raw);
    } catch (err) {
        console.warn("[HARNESS-GRAD] LLM call failed:", (err as Error).message);
        return [];
    }
}

// ── Prompt construction ─────────────────────────────────────────────────────

function buildPrompt(
    candidate: CandidateManifest,
    traces: TraceRecord[],
    bestScore: number,
): string {
    const registry = getRegistry();
    const dimLines = registry.map(dim => {
        const current = candidate.harnessConfig.dimensions[dim.id] ?? dim.defaultValue;
        const range = dim.minValue !== undefined ? ` [${dim.minValue}–${dim.maxValue}]` : "";
        const display = typeof current === "string"
            ? JSON.stringify(current).slice(0, 60)
            : JSON.stringify(current);
        return `- ${dim.id}: ${display}${range} — ${dim.description}`;
    });

    const failing = traces.filter(t => !t.taskSucceeded).slice(0, 10);
    const traceSummary = failing.length > 0
        ? failing.map(t =>
            `  FAIL "${t.queryText.slice(0, 60)}" tools=[${t.toolsSelected.slice(0, 3).join(",")}] evalScore=${t.evaluationScore ?? "n/a"} memHits=${t.memoryHitCount}`
        ).join("\n")
        : "  (no failing traces in this batch)";

    const scores = candidate.scores!;
    return `You are critiquing a harness configuration for an autonomous AI agent.

## Scores (composite ${scores.composite} vs best ${bestScore}, deficit ${(bestScore - scores.composite).toFixed(1)})
- task completion: ${scores.taskCompletionScore.toFixed(1)}/100
- memory recall: ${(scores.memoryRecallScore * 100).toFixed(1)}%
- tool selection: ${(scores.toolSelectionScore * 100).toFixed(1)}%
- token efficiency: ${(scores.tokenEfficiency * 100).toFixed(1)}%

## Current dimension values
${dimLines.join("\n")}

## Failing traces (most relevant evidence)
${traceSummary}

## Task
Identify the 3-5 dimensions most likely responsible for the score deficit.
Return a JSON object with a "gradients" key containing an array of gradient objects:
{"gradients":[{"dimensionId":"exact.id","currentValue":<current>,"critique":"one sentence with evidence","proposedDirection":"increase"|"decrease"|"rewrite","severity":"critical"|"moderate"|"minor"}]}
Return ONLY valid JSON. No markdown, no prose, no code fences.`;
}

function extractBestScore(benchmarkDetails: Record<string, unknown>, fallback: number): number {
    const b = benchmarkDetails["bestScore"];
    return (typeof b === "number" && Number.isFinite(b)) ? b : fallback;
}

// ── Parsing ─────────────────────────────────────────────────────────────────

function parseGradients(raw: string): DimensionGradient[] {
    if (!raw) return [];

    let candidates: unknown[] = [];

    // Try direct JSON parse first
    let parsed: unknown = undefined;
    try {
        parsed = JSON.parse(raw);
    } catch {
        // Tolerant extraction via json-extract (returns string | null)
        const extracted = extractJSON(raw);
        if (extracted) {
            try {
                parsed = JSON.parse(extracted);
            } catch { /* give up */ }
        }
    }

    if (Array.isArray(parsed)) {
        candidates = parsed;
    } else if (parsed && typeof parsed === "object") {
        const obj = parsed as Record<string, unknown>;
        // Handle {"gradients": [...]} — the expected format with responseFormat:json_object
        const arr = Object.values(obj).find(v => Array.isArray(v));
        if (arr) {
            candidates = arr as unknown[];
        } else {
            // Handle object-as-array with numeric keys {"0":{...},"1":{...}}
            const keys = Object.keys(obj);
            if (keys.length > 0 && keys.every(k => /^\d+$/.test(k))) {
                candidates = keys.sort((a, b) => Number(a) - Number(b)).map(k => obj[k]);
            }
        }
    }

    if (candidates.length === 0 && raw) {
        console.warn("[HARNESS-GRAD] Could not parse gradient response (returning []):", raw.substring(0, 200));
    }

    const out: DimensionGradient[] = [];
    for (const c of candidates) {
        if (!c || typeof c !== "object") continue;
        const o = c as Record<string, unknown>;
        if (typeof o.dimensionId !== "string") continue;
        if (typeof o.critique !== "string") continue;
        if (o.proposedDirection !== "increase" && o.proposedDirection !== "decrease" && o.proposedDirection !== "rewrite") continue;
        if (o.severity !== "critical" && o.severity !== "moderate" && o.severity !== "minor") continue;
        out.push({
            dimensionId: o.dimensionId,
            currentValue: o.currentValue,
            critique: o.critique,
            proposedDirection: o.proposedDirection,
            severity: o.severity,
        });
    }

    // Sort critical first, cap at MAX_GRADIENTS
    const rank: Record<DimensionGradient["severity"], number> = { critical: 3, moderate: 2, minor: 1 };
    out.sort((a, b) => rank[b.severity] - rank[a.severity]);
    return out.slice(0, MAX_GRADIENTS);
}

// ── Formatting ──────────────────────────────────────────────────────────────

/** Render gradients as markdown for gradient-hints.md in .metaharness/. */
export function formatGradientHints(gradients: DimensionGradient[]): string {
    if (gradients.length === 0) {
        return "# Dimension Gradients\n\n_No gradients generated for this candidate._\n";
    }
    const badge = (s: DimensionGradient["severity"]) =>
        s === "critical" ? "**[CRITICAL]**" : s === "moderate" ? "*[moderate]*" : "_[minor]_";

    const lines = ["# Dimension Gradients", ""];
    for (const g of gradients) {
        lines.push(`## ${g.dimensionId} ${badge(g.severity)}`);
        lines.push(`- Severity: ${g.severity}`);
        lines.push(`- Current value: \`${JSON.stringify(g.currentValue)}\``);
        lines.push(`- Proposed direction: **${g.proposedDirection}**`);
        lines.push(`- Critique: ${g.critique}`);
        lines.push("");
    }
    return lines.join("\n");
}
